package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        dto.setBulkSignupWarning(BulkSignup.warningRaised(ownerRepository));
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
===== EnsureUniqueIdentity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The duplicate block: rejects a create whose {@code (lastName, postcode)} household —
 * identified by its deterministic {@code householdId} (see {@link Households#householdId})
 * — is already occupied by an existing owner, as a 409 via
 * {@link DuplicateIdentityException}. Because the household is keyed on last name and
 * postcode, a second owner at the same one is a household duplicate.
 *
 * <p>A request that opts in with {@code sharesHousehold=true} bypasses the block: it is a
 * declared member of that household and is created (see {@link AssignPossibleDuplicate},
 * which also leaves a declared member unflagged). A request with no postcode has no
 * household key and cannot collide.
 *
 * <p>Runs before {@link BuildOwner}, so a collision is caught before any owner is built or
 * saved.
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = Households.householdId(request.getLastName(), request.getPostcode());
        if (householdId == null) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // a soft-deleted owner no longer occupies its household
            }
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(householdId);
            }
        }
    }
}
===== EnsureCityCapacity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityCapacityExceededException;

/**
 * Rejects a create request whose city already holds the maximum number of owners. Runs
 * before {@link BuildOwner}, so a full city is a 409 via
 * {@link CityCapacityExceededException} before any owner is built or saved. Cities are
 * counted case-insensitively (see {@link Cities}).
 */
public class EnsureCityCapacity {

    /** Maximum owners a single city may hold; the next create is rejected. */
    static final long MAX_OWNERS_PER_CITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityCapacityExceededException {
        if (Cities.countIn(ownerRepository, request.getCity()) >= MAX_OWNERS_PER_CITY) {
            throw new CityCapacityExceededException(request.getCity(), MAX_OWNERS_PER_CITY);
        }
    }
}
===== AuditOwnerCreated.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.util.MembershipLevel;

/**
 * Emits an audit trail entry for a successfully created owner. Runs after
 * {@link SaveOwner} (so the owner has its generated id) and before the response, logging
 * the owner id, customer code, registration date, membership level and membership number
 * to the dedicated {@code AUDIT} logger.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner) {
        AUDIT.info("Created owner id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                MembershipLevel.of(owner), owner.getMembershipNumber());
    }
}

